SELECT CAST(data ->> '$.commit.collection' AS CHAR(320)) COLLATE utf8mb4_bin AS event, COUNT(*) AS count FROM bluesky GROUP BY event ORDER BY count DESC;
SELECT CAST(data ->> '$.commit.collection' AS CHAR(320)) COLLATE utf8mb4_bin AS event, COUNT(*) AS count, COUNT(DISTINCT CAST(data ->> '$.did' AS CHAR(320)) COLLATE utf8mb4_bin) AS users FROM bluesky WHERE data ->> '$.kind' = 'commit' AND data ->> '$.commit.operation' = 'create' GROUP BY event ORDER BY count DESC;
SELECT CAST(data ->> '$.commit.collection' AS CHAR(320)) COLLATE utf8mb4_bin AS event, HOUR(TIMESTAMPADD(MICROSECOND, CAST(data ->> '$.time_us' AS UNSIGNED), TIMESTAMP '1970-01-01 00:00:00')) AS hour_of_day, COUNT(*) AS count FROM bluesky WHERE data ->> '$.kind' = 'commit' AND data ->> '$.commit.operation' = 'create' AND data ->> '$.commit.collection' IN ('app.bsky.feed.post', 'app.bsky.feed.repost', 'app.bsky.feed.like') GROUP BY event, hour_of_day ORDER BY hour_of_day, event;
SELECT CAST(data ->> '$.did' AS CHAR(320)) COLLATE utf8mb4_bin AS user_id, MIN(TIMESTAMPADD(MICROSECOND, CAST(data ->> '$.time_us' AS UNSIGNED), TIMESTAMP '1970-01-01 00:00:00')) AS first_post_ts FROM bluesky WHERE data ->> '$.kind' = 'commit' AND data ->> '$.commit.operation' = 'create' AND data ->> '$.commit.collection' = 'app.bsky.feed.post' GROUP BY user_id ORDER BY first_post_ts ASC LIMIT 3;
SELECT CAST(data ->> '$.did' AS CHAR(320)) COLLATE utf8mb4_bin AS user_id, TIMESTAMPDIFF(MICROSECOND, MIN(TIMESTAMPADD(MICROSECOND, CAST(data ->> '$.time_us' AS UNSIGNED), TIMESTAMP '1970-01-01 00:00:00')), MAX(TIMESTAMPADD(MICROSECOND, CAST(data ->> '$.time_us' AS UNSIGNED), TIMESTAMP '1970-01-01 00:00:00'))) / 1000 AS activity_span FROM bluesky WHERE data ->> '$.kind' = 'commit' AND data ->> '$.commit.operation' = 'create' AND data ->> '$.commit.collection' = 'app.bsky.feed.post' GROUP BY user_id ORDER BY activity_span DESC LIMIT 3;
